<?php
$allowed=['subjects'=>['name_en','name_si','name_ta','subject_code','icon'],'units'=>['name_en','name_si','name_ta','unit_number','subject_id'],'lessons'=>['title_en','title_si','title_ta','subject_id','unit_id'],'quizzes'=>['title_en','title_si','title_ta','subject_id','pass_mark']];if(!isset($allowed[$entity]))exit('Invalid catalog.');require_once __DIR__.'/../includes/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$action=$_POST['action']??'';if($id&&in_array($action,['active','inactive'],true)){$s=db()->prepare("UPDATE $entity SET status=? WHERE id=?");$s->bind_param('si',$action,$id);$s->execute();flash('success','Status updated.');header('Location: '.$entity.'.php');exit;}if($action==='add'){$data=[];foreach($allowed[$entity] as $f)$data[$f]=trim((string)($_POST[$f]??''));$data['grade_id']=1;$fields=array_keys($data);$marks=implode(',',array_fill(0,count($fields),'?'));$sql="INSERT INTO $entity(".implode(',',$fields).") VALUES($marks)";$s=db()->prepare($sql);$types='';$values=[];foreach($data as $f=>$v){$isInt=in_array($f,['grade_id','unit_number','subject_id','unit_id','pass_mark'],true);$types.=$isInt?'i':'s';$values[]=$isInt?(int)$v:$v;}$s->bind_param($types,...$values);if(!$s->execute())flash('error','Could not add item. Check required relationships and unique values.');else flash('success','Item added.');header('Location: '.$entity.'.php');exit;}}$pageTitle=ucfirst($entity);include __DIR__.'/_top.php';$rows=db()->query("SELECT * FROM $entity ORDER BY id DESC");?><h1><?=e(ucfirst($entity))?></h1><section class="card"><h2>Add <?=e(rtrim($entity,'s'))?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><?php foreach($allowed[$entity] as $f):?><label><?=e(ucwords(str_replace('_',' ',$f)))?><input name="<?=e($f)?>" required></label><?php endforeach;?><button>Add</button></form></section><section class="card scroll"><table><tr><th>ID</th><th>Name/title</th><th>Status</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=$r['id']?></td><td><?=e($r['name_en']??$r['title_en']??'')?></td><td><?=e($r['status'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="<?=$r['status']==='active'?'danger':'good'?>" name="action" value="<?=$r['status']==='active'?'inactive':'active'?>"><?=$r['status']==='active'?'Deactivate':'Activate'?></button></form></td></tr><?php endwhile;?></table></section><?php if($entity==='quizzes'):?><section class="card"><p>Quiz questions are multilingual database records. Add/edit them in <code>quiz_questions</code> through phpMyAdmin in this initial admin build.</p></section><?php endif;include __DIR__.'/../includes/footer.php';?>
